var _dn = SLP.books.find(function(b){ return b.id === "dan"; });
if (!_dn) throw new Error("data/canon.js must load before ot-32-dan-hosea.js");
(_dn.chapters = _dn.chapters || []).push(
  { n:1, summary:"Nebuchadnezzar comes to Jerusalem in the third year of Jehoiakim; the Lord gives the king of Judah into his hand along with part of the vessels of the house of God, carried to the treasure house of his god in Shinar. The king orders Ashpenaz to select promising Israelite youths, well favoured, skilful, and able to stand in the palace, for three years of training in the learning and tongue of the Chaldeans, fed from the king's own meat and wine. Among them are Daniel, Hananiah, Mishael, and Azariah, given Babylonian names. Daniel purposes in his heart not to defile himself with the king's portion and negotiates a ten-day trial of pulse and water with Melzar. At the end of ten days they look fairer than their companions, keep the diet, and after three years the king finds them ten times better than all his magicians and astrologers. Daniel continues unto the first year of Cyrus.",
    context:"Set in the third year of Jehoiakim king of Judah, when Nebuchadnezzar of Babylon besieged Jerusalem and carried captives and temple vessels to Shinar.",
    keyVerses:[
      { ref:"Daniel 1:8", text:"But Daniel purposed in his heart that he would not defile himself with the portion of the king's meat, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself." },
      { ref:"Daniel 1:17", text:"As for these four children, God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams." },
      { ref:"Daniel 1:20", text:"And in all matters of wisdom and understanding, that the king inquired of them, he found them ten times better than all the magicians and astrologers that were in all his realm." }
    ],
    takeaway:"Purpose in your heart to be true to God first, and He adds wisdom and favor.",
    quiz:[
      { q:"How many days did Daniel ask to be proved with pulse and water?", choices:["Ten days","Three days","Forty days","One year"], a:0, why:"Daniel asked Melzar to prove the four servants ten days with pulse and water, and at the end their countenances appeared fairer than the children who ate the king's meat." },
      { q:"Why did Daniel refuse the king's meat and wine?", choices:["Because the meat was spoiled","Because he had purposed in his heart not to defile himself with them","Because he was allergic to wine","Because Melzar ordered him not to eat it"], a:1, why:"Verse 8 says Daniel purposed in his heart that he would not defile himself with the portion of the king's meat, nor with the wine which he drank." },
      { q:"What does Daniel 1 teach about obedient self-discipline?", choices:["It makes life harder with no reward","It only matters for priests","God gives knowledge and skill to those who keep themselves pure","Diets matter more than prayer"], a:2, why:"The four who kept themselves clean received knowledge and skill in all learning and wisdom, and the king found them ten times better than all his magicians and astrologers." }
    ] },
  { n:2, summary:"In the second year of his reign, Nebuchadnezzar dreams a dream that troubles him and demands that his wise men tell both the dream and its interpretation, on pain of death. They answer that no man on earth can do it, only the gods, so the king decrees the destruction of all the wise men of Babylon, Daniel and his fellows included. Daniel asks for time, and he and his three companions seek mercies of the God of heaven. The secret comes in a night vision, and Daniel blesses the God who removeth kings and setteth up kings. He tells the king of a great image of gold, silver, brass, iron, and clay, broken by a stone cut without hands that becomes a mountain filling the whole earth, the kingdom of God that shall stand for ever. Nebuchadnezzar worships and promotes Daniel and his three friends.",
    context:"Spoken to Nebuchadnezzar in the second year of his reign, when the king demanded of his wise men both the dream and its interpretation.",
    keyVerses:[
      { ref:"Daniel 2:19", text:"Then was the secret revealed unto Daniel in a night vision. Then Daniel blessed the God of heaven." },
      { ref:"Daniel 2:44", text:"And in the days of these kings shall the God of heaven set up a kingdom, which shall never be destroyed: and the kingdom shall not be left to other people, but it shall break in pieces and consume all these kingdoms, and it shall stand for ever." },
      { ref:"Daniel 2:47", text:"The king answered unto Daniel, and said, Of a truth it is, that your God is a God of gods, and a Lord of kings, and a revealer of secrets, seeing thou couldest reveal this secret." }
    ],
    takeaway:"God reveals secrets and sets up kingdoms; His kingdom, cut without human hands, stands forever.",
    quiz:[
      { q:"What happened to the image's feet of iron and clay in the dream?", choices:["They were gilded with gold","A stone cut without hands broke them to pieces","Water rose and dissolved them","They grew into a forest"], a:2, why:"The stone cut out without hands smote the image upon his feet of iron and clay and broke the whole image to pieces like the chaff of summer threshingfloors." },
      { q:"What did the four-part image with its different metals represent?", choices:["Four temples Nebuchadnezzar planned","The planets and their powers","Daniel's four friends and their ranks","A succession of earthly kingdoms, beginning with Nebuchadnezzar's"], a:3, why:"Daniel explains that Nebuchadnezzar was the head of gold and that other kingdoms would arise after him, each in turn, until God's own kingdom came." },
      { q:"What assurance does the stone kingdom give believers?", choices:["God will set up a kingdom that shall never be destroyed","Babylon will be rebuilt in glory","Wise men can interpret every dream","Earthly empires last forever"], a:0, why:"In the days of those kings the God of heaven sets up a kingdom which shall never be destroyed, and it shall stand for ever." }
    ] },
  { n:3, summary:"Nebuchadnezzar sets up a golden image sixty cubits high in the plain of Dura and commands every official, people, nation, and language to fall down and worship it when the music sounds, on pain of the burning fiery furnace. Certain Chaldeans accuse the Jews, naming Shadrach, Meshach, and Abed-nego as men who refuse the king's gods and his image. Brought before the furious king, the three answer that their God is able to deliver them, but even if He does not, they will not serve the king's gods. The furnace is heated seven times hotter, and the mighty men who throw them in are slain by the flame. Yet the astonished king sees four men loose in the fire, and the form of the fourth is like the Son of God. The three come out without even the smell of fire, the king blesses their God, and they are promoted in the province.",
    context:"Under Nebuchadnezzar in Babylon, the three Hebrews set over the affairs of the province face the king's worship decree on the plain of Dura.",
    keyVerses:[
      { ref:"Daniel 3:17", text:"If it be so, our God whom we serve is able to deliver us from the burning fiery furnace, and he will deliver us out of thine hand, O king." },
      { ref:"Daniel 3:18", text:"But if not, be it known unto thee, O king, that we will not serve thy gods, nor worship the golden image which thou hast set up." },
      { ref:"Daniel 3:25", text:"He answered and said, Lo, I see four men loose, walking in the midst of the fire, and they have no hurt; and the form of the fourth is like the Son of God." }
    ],
    takeaway:"Trust God's power to deliver, and stay faithful even if He chooses not to rescue.",
    quiz:[
      { q:"How many times hotter than usual was the furnace heated?", choices:["Twice","Seven times","Ten times","A hundred times"], a:1, why:"The king commanded that the furnace be heated one seven times more than it was wont to be heated." },
      { q:"What did Nebuchadnezzar see when he looked into the furnace?", choices:["Only ashes and bones","Nothing; the fire went out","Four men loose in the fire, the fourth like the Son of God","The three Hebrews burning"], a:2, why:"The king rose in haste and said he saw four men loose, walking in the fire without hurt, and the form of the fourth was like the Son of God." },
      { q:"What is the 'but if not' faith of the three Hebrews?", choices:["Faith that God will always prevent suffering","Faith that ends when trials begin","Obedience only when it is safe","Faithfulness to God whether or not He delivers"], a:3, why:"They said God was able to deliver them, but if not, they still would not serve the king's gods nor worship the golden image." }
    ] },
  { n:4, summary:"Nebuchadnezzar writes this chapter as a testimony of the signs and wonders the high God wrought toward him. At rest in his palace he dreams of a great tree in the midst of the earth, until a watcher from heaven cries that it be hewn down, its stump banded with iron and brass, and a beast's heart given it until seven times pass over. Daniel is astonished and interprets: the tree is the king, who will be driven from men to eat grass as oxen until he learns that the most High ruleth in the kingdom of men. Daniel urges him to break off his sins by righteousness and show mercy to the poor. Twelve months later the king boasts over the great Babylon he has built; a voice declares the kingdom departed, and the madness falls. When his reason returns he blesses the King of heaven, who is able to abase those that walk in pride, and his kingdom is restored.",
    context:"A proclamation of Nebuchadnezzar to all peoples, recounting his dream, his madness, and his restoration under the King of heaven.",
    keyVerses:[
      { ref:"Daniel 4:25", text:"That they shall drive thee from men, and thy dwelling shall be with the beasts of the field, and they shall make thee to eat grass as oxen, and they shall wet thee with the dew of heaven, and seven times shall pass over thee, till thou know that the most High ruleth in the kingdom of men, and giveth it to whomsoever he will." },
      { ref:"Daniel 4:34", text:"And at the end of the days I Nebuchadnezzar lifted up mine eyes unto heaven, and mine understanding returned unto me, and I blessed the most High, and I praised and honoured him that liveth for ever, whose dominion is an everlasting dominion, and his kingdom is from generation to generation:" },
      { ref:"Daniel 4:37", text:"Now I Nebuchadnezzar praise and extol and honour the King of heaven, all whose works are truth, and his ways judgment: and those that walk in pride he is able to abase." }
    ],
    takeaway:"The most High rules in the kingdom of men, and He is able to abase those who walk in pride.",
    quiz:[
      { q:"What did Nebuchadnezzar eat during his seven-times madness?", choices:["Fine bread from the king's table","Herbs like Daniel's pulse","Grass as oxen, wet with the dew of heaven","Locusts and wild honey"], a:2, why:"He was driven from men, did eat grass as oxen, and his body was wet with the dew of heaven until the appointed days were fulfilled." },
      { q:"What lesson was the tree dream meant to teach Nebuchadnezzar?", choices:["That Babylon needed new gardens","That trees are sacred symbols","That Daniel could predict weather","That the most High rules in the kingdom of men and gives it to whomsoever He will"], a:3, why:"The decree came so that the living may know that the most High ruleth in the kingdom of men, and the king confessed it when his reason returned." },
      { q:"What does the chapter show about pride?", choices:["Pride secures a lasting throne","God resists the proud but restores the humble who acknowledge Him","Pride is rewarded with wisdom","Humility is only for the poor"], a:1, why:"Nebuchadnezzar's boasting brought madness, but when he lifted his eyes to heaven and blessed the most High, his honour returned; those that walk in pride He is able to abase." }
    ] },
  { n:5, summary:"Belshazzar the king makes a great feast for a thousand of his lords and, tasting the wine, commands the golden and silver vessels taken from the temple at Jerusalem to be brought in, so his court drinks from them while praising gods of gold, silver, brass, iron, wood, and stone. Then fingers of a man's hand write on the palace wall, and the terrified king promises scarlet, a chain of gold, and third rule to whoever can read it. The wise men fail, until the queen recalls Daniel, who dissolved doubts in Nebuchadnezzar's day. Daniel refuses the rewards, recounts how God humbled Nebuchadnezzar's pride, and charges that Belshazzar, his son, had not humbled his heart though he knew all this. He reads the writing: God hath numbered thy kingdom and finished it; thou art weighed in the balances and found wanting; thy kingdom is divided and given to the Medes and Persians. That night Belshazzar is slain, and Darius the Median takes the kingdom.",
    context:"Set at Belshazzar's feast in Babylon, the night the Medes and Persians took the city and Darius the Median received the kingdom.",
    keyVerses:[
      { ref:"Daniel 5:22", text:"And thou his son, O Belshazzar, hast not humbled thine heart, though thou knewest all this;" },
      { ref:"Daniel 5:27", text:"TEKEL; Thou art weighed in the balances, and art found wanting." },
      { ref:"Daniel 5:30", text:"In that night was Belshazzar the king of the Chaldeans slain." }
    ],
    takeaway:"God weighs rulers and nations; what He has numbered will not stand without His favor.",
    quiz:[
      { q:"What words did the hand write on the wall?", choices:["MENE, MENE, TEKEL, UPHARSIN","ELI, ELI, LAMA SABACHTHANI","WRITING ON THE DOORPOSTS","ABADDON AND APOLLYON"], a:0, why:"This is the writing that was written, MENE, MENE, TEKEL, UPHARSIN, over against the candlestick upon the plaster of the wall." },
      { q:"Why did Daniel condemn Belshazzar so sharply?", choices:["He refused to pay Daniel's fee","He knew of Nebuchadnezzar's humbling yet did not humble his own heart","He had banished Daniel from Babylon","He worshipped too many gods of stone"], a:1, why:"Daniel says, Thou his son, O Belshazzar, hast not humbled thine heart, though thou knewest all this, but hast lifted up thyself against the Lord of heaven." },
      { q:"What does TEKEL, weighed in the balances and found wanting, teach?", choices:["God never evaluates human conduct","Only nations, not persons, are judged","God weighs hearts, and hidden sins are not hidden from Him","Wealth measures a person's worth"], a:2, why:"The God in whose hand our breath is saw what Belshazzar did with sacred things, and the writing announced that He had weighed him and found him wanting." }
    ] },
  { n:6, summary:"Darius organizes his new kingdom with a hundred and twenty princes and three presidents, setting Daniel first because an excellent spirit was in him. Jealous rivals hunt for fault in his handling of the kingdom but find none, concluding they can only catch him concerning the law of his God. They flatter Darius into signing a decree that for thirty days no one may pray to any god or man but the king, on pain of the lions' den. Knowing it is signed, Daniel goes home, opens his windows toward Jerusalem, and prays three times a day as before. Caught in the act, he is cast into the den, though the king labors to save him and trusts that Daniel's God will deliver him. An angel shuts the lions' mouths; Daniel is lifted out without hurt because he believed in his God, the accusers are cast in, and Darius publishes a decree that men tremble and fear before the living God of Daniel.",
    context:"Under Darius the Mede, who took the kingdom at about sixty-two years of age, Daniel serves as first of three presidents over the realm.",
    keyVerses:[
      { ref:"Daniel 6:10", text:"Now when Daniel knew that the writing was signed, he went into his house; and his windows being open in his chamber toward Jerusalem, he kneeled upon his knees three times a day, and prayed, and gave thanks before his God, as he did aforetime." },
      { ref:"Daniel 6:22", text:"My God hath sent his angel, and hath shut the lions' mouths, that they have not hurt me: forasmuch as before him innocency was found in me; and also before thee, O king, have I done no hurt." },
      { ref:"Daniel 6:26", text:"I make a decree, That in every dominion of my kingdom men tremble and fear before the God of Daniel: for he is the living God, and steadfast for ever, and his kingdom that which shall not be destroyed, and his dominion shall be even unto the end." }
    ],
    takeaway:"Consistent, unhidden devotion honors God more than safety does; He honors those who honor Him.",
    quiz:[
      { q:"How often did Daniel pray and give thanks, as he did aforetime?", choices:["Once a week","Twice a day","Seven times a day","Three times a day"], a:3, why:"He kneeled upon his knees three times a day, and prayed, and gave thanks before his God, with his windows open toward Jerusalem." },
      { q:"Why did Daniel's rivals think a religious law was their only trap?", choices:["He was faithful in the kingdom's business, with no error or fault found in him","He was too popular to accuse otherwise","He controlled the army","The king forbade them to tax him"], a:0, why:"The presidents and princes could find no occasion nor fault in his administration, so they sought it against the law of his God." },
      { q:"What made Daniel's courage in the den possible?", choices:["He knew the king secretly loved him","He believed in his God and maintained innocency before God and the king","He had trained the lions","He planned to escape at night"], a:1, why:"No manner of hurt was found upon him because he believed in his God, and he told the king that innocency was found in him before God and before the king." }
    ] },
  { n:7, summary:"In the first year of Belshazzar, Daniel dreams of four winds striving on the great sea as four great beasts rise in turn: a lion with eagle's wings, a bear with three ribs in its mouth, a four-headed winged leopard, and a dreadful fourth beast with iron teeth and ten horns, from which a little horn with eyes and a boasting mouth uproots three. Then the Ancient of days sits in judgment, white as snow, with fiery stream before him and thousand thousands ministering; the books are opened, the beast is slain, and one like the Son of man comes with the clouds of heaven to receive everlasting dominion, glory, and a kingdom that all people should serve him. An interpreter explains that the beasts are four kings, but the saints of the most High shall take and possess the kingdom for ever. The little horn wars against the saints until the Ancient of days comes and judgment is given to them.",
    context:"A dream given to Daniel in the first year of Belshazzar king of Babylon, written down as the sum of the matters.",
    keyVerses:[
      { ref:"Daniel 7:9", text:"I beheld till the thrones were cast down, and the Ancient of days did sit, whose garment was white as snow, and the hair of his head like the pure wool: his throne was like the fiery flame, and his wheels as burning fire." },
      { ref:"Daniel 7:13", text:"I saw in the night visions, and, behold, one like the Son of man came with the clouds of heaven, and came to the Ancient of days, and they brought him near before him." },
      { ref:"Daniel 7:18", text:"But the saints of the most High shall take the kingdom, and possess the kingdom for ever, even for ever and ever." }
    ],
    takeaway:"Earthly kingdoms rise and fall, but the Son of man's dominion is everlasting, and the saints inherit it.",
    quiz:[
      { q:"How many horns did the dreadful fourth beast have?", choices:["Three","Seven","Ten","Twelve"], a:2, why:"The fourth beast had great iron teeth and ten horns, and a little horn came up among them before whom three of the first horns fell." },
      { q:"Who received dominion and glory when the judgment sat?", choices:["The little horn","The four beasts together","The Ancient of days' angels","One like the Son of man, coming with the clouds of heaven"], a:3, why:"Daniel saw one like the Son of man brought near before the Ancient of days, to whom was given an everlasting dominion that shall not pass away." },
      { q:"What hope does Daniel 7 give the persecuted?", choices:["The saints of the most High will possess the kingdom for ever","Earthly powers will reform themselves","Visions and dreams are meaningless","The sea will swallow every empire"], a:0, why:"Though the horn made war with the saints and prevailed for a season, judgment was given to the saints, and the time came that they possessed the kingdom." }
    ] },
  { n:8, summary:"In the third year of Belshazzar, Daniel sees a vision by the river Ulai: a ram with two horns, the higher coming up last, pushes in every direction until none can stand before him, but a he-goat from the west with a notable horn strikes him down in fury. When the goat waxed very great, his great horn broke and four notable horns rose toward the four winds, and out of one came a little horn that waxed exceeding great toward the pleasant land, cast down some of the host and of the stars, took away the daily sacrifice, and cast truth to the ground. Gabriel is sent to make Daniel understand: the ram is the kings of Media and Persia, the rough goat is the king of Grecia, and his great horn is the first king. A fierce king of the latter time shall stand up against the Prince of princes, but shall be broken without hand. Daniel faints, is sick certain days, then does the king's business.",
    context:"A vision given Daniel in the third year of king Belshazzar, seen at Shushan in the palace by the river of Ulai in Elam.",
    keyVerses:[
      { ref:"Daniel 8:14", text:"And he said unto me, Unto two thousand and three hundred days; then shall the sanctuary be cleansed." },
      { ref:"Daniel 8:20", text:"The ram which thou sawest having two horns are the kings of Media and Persia." },
      { ref:"Daniel 8:21", text:"And the rough goat is the king of Grecia: and the great horn that is between his eyes is the first king." }
    ],
    takeaway:"Earthly powers have their appointed hours; even powers that defy the Prince of princes are broken without hand.",
    quiz:[
      { q:"According to Gabriel, what did the two-horned ram represent?", choices:["The kings of Egypt and Libya","The kings of Media and Persia","The kings of Rome and Greece","Judah and Israel"], a:1, why:"Gabriel explains that the ram with two horns are the kings of Media and Persia, the higher horn coming up last." },
      { q:"What happened to the he-goat's great horn, and what followed?", choices:["It grew until it filled the sky","It became an eternal throne","It was broken when the goat was strong, and four kingdoms rose toward the four winds","It turned into a ram's horn"], a:2, why:"When the goat waxed very great, the great horn was broken, and for it came up four notable ones toward the four winds of heaven." },
      { q:"What limit does the vision place on arrogant power?", choices:["None; craft always prospers","Kings answer only to their armies","Visions cannot be understood","Even a king who stands against the Prince of princes shall be broken without hand"], a:3, why:"Gabriel says the fierce king shall magnify himself in his heart and stand up against the Prince of princes, but he shall be broken without hand." }
    ] },
  { n:9, summary:"In the first year of Darius, Daniel reads in the books that the word of the Lord to Jeremiah appointed seventy years for the desolations of Jerusalem, so he sets his face to seek God with fasting, sackcloth, and ashes. His prayer confesses national sin: we have sinned and done wickedly, departing from God's precepts and refusing the prophets, so the curse written in the law of Moses has been poured out. Righteousness belongs to the Lord; mercies and forgivenesses belong to Him too, and Daniel pleads not in his own righteousness but for God's great mercies, that His face may shine on the desolate sanctuary. Gabriel comes swiftly at the evening oblation, saying, Thou art greatly beloved, and unfolds seventy weeks determined upon Daniel's people and holy city: from the commandment to restore and build Jerusalem unto Messiah the Prince shall be seven weeks and threescore and two weeks; Messiah shall be cut off, but not for himself.",
    context:"Prayed in the first year of Darius the Mede, when Daniel understood by Jeremiah's writings that the desolations of Jerusalem would last seventy years.",
    keyVerses:[
      { ref:"Daniel 9:9", text:"To the Lord our God belong mercies and forgivenesses, though we have rebelled against him;" },
      { ref:"Daniel 9:24", text:"Seventy weeks are determined upon thy people and upon thy holy city, to finish the transgression, and to make an end of sins, and to make reconciliation for iniquity, and to bring in everlasting righteousness, and to seal up the vision and prophecy, and to anoint the most Holy." },
      { ref:"Daniel 9:25", text:"Know therefore and understand, that from the going forth of the commandment to restore and to build Jerusalem unto the Messiah the Prince shall be seven weeks, and threescore and two weeks: the street shall be built again, and the wall, even in troublous times." }
    ],
    takeaway:"We are heard not for our righteousness but for God's great mercies; He answers seeking hearts with understanding.",
    quiz:[
      { q:"Whose prophecy did Daniel consult to learn that Jerusalem's desolations would last seventy years?", choices:["Jeremiah","Isaiah","Ezekiel","Moses"], a:0, why:"Daniel understood by books the word of the LORD that came to Jeremiah the prophet, that he would accomplish seventy years in the desolations of Jerusalem." },
      { q:"What was determined within the seventy weeks upon Daniel's people and holy city?", choices:["Four more captivities","To finish the transgression, make an end of sins, bring in everlasting righteousness, and anoint the most Holy","The rebuilding of Babylon","A new kingdom of brass"], a:1, why:"Verse 24 lists these purposes: to finish the transgression, make reconciliation for iniquity, bring in everlasting righteousness, seal up vision and prophecy, and anoint the most Holy." },
      { q:"What does Daniel's prayer model for approaching God after failure?", choices:["Blaming the prophets for the exile","Minimizing sin to feel better","Honest confession resting on God's mercies and forgivenesses","Silence until the punishment ends"], a:2, why:"Daniel confesses plainly that all Israel transgressed, yet appeals to the God to whom belong mercies and forgivenesses, not to his own righteousness." }
    ] },
  { n:10, summary:"In the third year of Cyrus king of Persia, after mourning three full weeks without pleasant bread, flesh, wine, or anointing, Daniel stands by the river Hiddekel and sees a man clothed in linen, girded with fine gold of Uphaz, whose face is like lightning and voice like a multitude. The men with him flee to hide; Daniel alone is left without strength, face to the ground. A hand touches him, and the messenger says his words were heard from the first day he set his heart to understand, but the prince of the kingdom of Persia withstood him one and twenty days until Michael, one of the chief princes, came to help. Twice more he touches Daniel and says, O man greatly beloved, fear not: peace be unto thee, be strong. Strengthened, Daniel hears that the messenger must return to fight the prince of Persia, and that the prince of Grecia shall come.",
    context:"A revelation in the third year of Cyrus king of Persia, after Daniel had mourned and fasted three full weeks by the river Hiddekel.",
    keyVerses:[
      { ref:"Daniel 10:12", text:"Then said he unto me, Fear not, Daniel: for from the first day that thou didst set thine heart to understand, and to chasten thyself before thy God, thy words were heard, and I am come for thy words." },
      { ref:"Daniel 10:13", text:"But the prince of the kingdom of Persia withstood me one and twenty days: but, lo, Michael, one of the chief princes, came to help me;" },
      { ref:"Daniel 10:19", text:"And said, O man greatly beloved, fear not: peace be unto thee, be strong, yea, be strong. And when he had spoken unto me, I was strengthened, and said, Let my lord speak; for thou hast strengthened me." }
    ],
    takeaway:"Humble seeking is heard from the very first day, even when the answer is long in coming.",
    quiz:[
      { q:"How long did the messenger say he had been withstood by the prince of Persia?", choices:["Seven days","Three weeks of years","Forty days","One and twenty days"], a:3, why:"He says the prince of the kingdom of Persia withstood him one and twenty days, until Michael, one of the chief princes, came to help him." },
      { q:"What was happening while Daniel mourned and waited for understanding?", choices:["A spiritual conflict delayed the messenger sent to him","God had forgotten his prayer","The king had banned Daniel from court","Daniel's companions were praying against him"], a:0, why:"The messenger explains that he was withstood by the prince of the kingdom of Persia for twenty-one days until Michael came to help." },
      { q:"What comfort does the phrase 'from the first day... thy words were heard' give?", choices:["Answers always arrive within three weeks","God hears sincere seeking immediately, even before visible results appear","Only fasts of twenty-one days are valid","Angels need our permission to help"], a:1, why:"The messenger tells Daniel that from the first day he set his heart to understand and chastened himself before his God, his words were heard." }
    ] },
  { n:11, summary:"The heavenly messenger continues the vision begun in Cyrus's time, unfolding successive conflicts: three more kings in Persia, then a mighty king whose kingdom breaks toward the four winds and is not given to his posterity. Kingdoms of the south and north collide for generations: royal marriages fail, armies overflow and return, and the glorious land is entered by force. A vile person obtains the kingdom by flatteries, pollutes the sanctuary, takes away the daily sacrifice, and places the abomination that maketh desolate, corrupting by flatteries those who act wickedly against the covenant. Yet the people that do know their God shall be strong and do exploits, and they that understand instruct many, falling to try, purge, and make them white even to the time of the end. The final king exalts himself above every god, honors a strange god, and plants his palace in the glorious holy mountain, yet comes to his end, and none shall help him.",
    context:"Continuation of the revelation begun in the third year of Cyrus, opening with events from the first year of Darius the Mede.",
    keyVerses:[
      { ref:"Daniel 11:3", text:"And a mighty king shall stand up, that shall rule with great dominion, and do according to his will." },
      { ref:"Daniel 11:32", text:"And such as do wickedly against the covenant shall he corrupt by flatteries: but the people that do know their God shall be strong, and do exploits." },
      { ref:"Daniel 11:35", text:"And some of them of understanding shall fall, to try them, and to purge, and to make them white, even to the time of the end: because it is yet for a time appointed." }
    ],
    takeaway:"The people that do know their God shall be strong and do exploits, even in times of trouble.",
    quiz:[
      { q:"Which two kingdoms does the chapter's long prophecy keep clashing?", choices:["Persia and Media","Egypt and Ethiopia","The king of the north and the king of the south","Israel and Judah"], a:2, why:"The vision follows the king of the south and the king of the north through wars, leagues, and betrayals across many generations." },
      { q:"What does the vile person do against the holy covenant?", choices:["He restores the daily sacrifice","He converts to the God of Jacob","He builds the temple anew","He pollutes the sanctuary, takes away the daily sacrifice, and places the abomination that maketh desolate"], a:3, why:"Arms stand on his part, they pollute the sanctuary of strength, take away the daily sacrifice, and place the abomination that maketh desolate." },
      { q:"What happens to those who do know their God during such corruption?", choices:["They shall be strong and do exploits, instructing many even at cost","They escape every trial unharmed","They retreat into silence","They join the flatterers for safety"], a:0, why:"The people that do know their God shall be strong and do exploits; they that understand instruct many, though some fall to try, purge, and make them white." }
    ] },
  { n:12, summary:"At that time Michael, the great prince who stands for Daniel's people, shall stand up, and a time of trouble comes such as never was since there was a nation, yet the people are delivered, every one found written in the book. Many of them that sleep in the dust of the earth awake, some to everlasting life and some to shame and everlasting contempt; the wise shine as the firmament, and they that turn many to righteousness as the stars for ever. Daniel is told to seal the book even to the time of the end, when many shall run to and fro and knowledge shall be increased. The man clothed in linen above the river swears it is for a time, times, and an half; many shall be purified and tried, the wicked shall do wickedly, but the wise shall understand. Daniel is promised rest, and that he shall stand in his lot at the end of the days.",
    context:"The closing scene of Daniel's final vision: a time of trouble, deliverance, resurrection, and a sealed book till the time of the end.",
    keyVerses:[
      { ref:"Daniel 12:1", text:"And at that time shall Michael stand up, the great prince which standeth for the children of thy people: and there shall be a time of trouble, such as never was since there was a nation even to that same time: and at that time thy people shall be delivered, every one that shall be found written in the book." },
      { ref:"Daniel 12:2", text:"And many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt." },
      { ref:"Daniel 12:3", text:"And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever." }
    ],
    takeaway:"God keeps a book, wakes the sleeping dust, and reserves rest and a lot for those who wait for the end.",
    quiz:[
      { q:"Which prince stands up for the children of Daniel's people in that day?", choices:["Gabriel","Michael, the great prince","Arioch","Melzar"], a:1, why:"At that time shall Michael stand up, the great prince which standeth for the children of thy people." },
      { q:"What happens to those who sleep in the dust of the earth?", choices:["They sleep forever without waking","Only the righteous awaken","Many awake, some to everlasting life and some to shame and everlasting contempt","They become like the stars"], a:2, why:"Many of them that sleep in the dust of the earth shall awake, some to everlasting life, and some to shame and everlasting contempt." },
      { q:"What final promise settles Daniel's heart?", choices:["He will see Babylon fall in his lifetime","His book will be published at once","He will rule Persia","Thou shalt rest, and stand in thy lot at the end of the days"], a:3, why:"The messenger sends him on his way till the end be, promising that he shall rest and stand in his lot at the end of the days." }
    ] }
);
